CREATE TABLE scopes (id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, city TEXT, timezone TEXT NOT NULL, osmAreaId INTEGER);
CREATE TABLE sources (id TEXT PRIMARY KEY, providerId TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', scopeId TEXT NOT NULL REFERENCES scopes(id), language TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT 'all', categories TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 0, priority INTEGER NOT NULL DEFAULT 50, notes TEXT NOT NULL DEFAULT '', format TEXT NOT NULL DEFAULT 'auto', keyword TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'configured', lastSyncAt TEXT, lastTestAt TEXT, lastAttemptAt TEXT, lastError TEXT, lastResult TEXT);
CREATE TABLE entities (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('Event','Place','Community','Organizer')), title TEXT NOT NULL, country TEXT NOT NULL, city TEXT NOT NULL, startAt TEXT NOT NULL DEFAULT '', data TEXT NOT NULL CHECK(json_valid(data)), overrides TEXT NOT NULL DEFAULT '{}', archived INTEGER NOT NULL DEFAULT 0, favorite INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX entities_location ON entities(country,city,type);
CREATE INDEX entities_start ON entities(startAt);
CREATE TABLE source_items (id TEXT PRIMARY KEY, sourceId TEXT NOT NULL REFERENCES sources(id), externalId TEXT NOT NULL, sourceUrl TEXT NOT NULL DEFAULT '', rawText TEXT NOT NULL, rawPayload TEXT NOT NULL CHECK(json_valid(rawPayload)), publishedAt TEXT, fetchedAt TEXT NOT NULL, checksum TEXT NOT NULL, UNIQUE(sourceId,externalId,checksum));
CREATE INDEX source_items_external ON source_items(sourceId,externalId);
CREATE TABLE entity_source_links (entityId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, sourceItemId TEXT NOT NULL REFERENCES source_items(id), PRIMARY KEY(entityId,sourceItemId));
CREATE INDEX source_links_item ON entity_source_links(sourceItemId);
CREATE TABLE entity_keys (key TEXT NOT NULL, entityId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, PRIMARY KEY(key,entityId));
CREATE TABLE entity_relations (fromId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, toId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, relation TEXT NOT NULL CHECK(relation IN ('organizes','hosts','recommends','associated')), PRIMARY KEY(fromId,toId,relation), CHECK(fromId != toId));
CREATE TABLE duplicate_pairs (firstId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, secondId TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', PRIMARY KEY(firstId,secondId), CHECK(firstId < secondId));
CREATE TABLE source_candidates (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL UNIQUE, discoveredFrom TEXT NOT NULL REFERENCES source_items(id), probableType TEXT NOT NULL, scopeId TEXT NOT NULL REFERENCES scopes(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', entityId TEXT REFERENCES entities(id) ON DELETE SET NULL);
CREATE TABLE sync_runs (id TEXT PRIMARY KEY,sourceId TEXT NOT NULL REFERENCES sources(id),startedAt TEXT NOT NULL,finishedAt TEXT,status TEXT NOT NULL,fetched INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL DEFAULT 0,duplicates INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,warnings TEXT NOT NULL DEFAULT '[]',error TEXT);
